// The sample data covers 2026-07-29 to 2026-09-28. Each real day replays the next sample day, looping.
const first = Date.UTC(2026, 6, 29);
const daysSince = Math.floor((Date.now() - Date.UTC(2026, 10, 1)) / 86400000);
const offset = ((daysSince % 62) + 62) % 62;
return [{ json: { date: new Date(first + offset * 86400000).toISOString().slice(0, 10) } }];

// ===== Sample data generator (replace generate() with a query on your own warehouse) =====
// ZipBasket (fictional 10-minute grocery app): deterministic sample data with planted incidents.
// Pure JS, no dependencies, so the same code runs inside an n8n Code node.

function makeRng(seed) {
  let a = seed >>> 0;
  return function () {
    a = (a + 0x6D2B79F5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

const START = '2026-07-01';
const DAYS = 90;
const CITIES = {
  Bengaluru: { base: 4200, stores: ['Koramangala', 'Indiranagar', 'HSR Layout', 'Whitefield', 'Jayanagar'] },
  Delhi: { base: 4000, stores: ['Saket', 'Dwarka', 'Rohini', 'Lajpat Nagar', 'Karol Bagh'] },
  Mumbai: { base: 3800, stores: ['Andheri', 'Bandra', 'Powai', 'Thane', 'Dadar'] },
  Hyderabad: { base: 3000, stores: ['Gachibowli', 'Madhapur', 'Kondapur', 'Banjara Hills', 'Kukatpally'] }
};
const WEEKDAY = [1.15, 0.92, 0.90, 0.93, 0.95, 1.05, 1.18]; // Sun..Sat
const USERS = {
  new: { share: 0.15, checkout: 0.115, items: 3.6 },
  repeat: { share: 0.85, checkout: 0.17, items: 5.4 }
};
const PAYMENTS = { UPI: { share: 0.70, success: 0.94 }, Card: { share: 0.15, success: 0.92 }, COD: { share: 0.15, success: 0.99 } };
const CATEGORIES = {
  dairy: { share: 0.22, price: 55 }, fruits_veg: { share: 0.25, price: 60 }, snacks: { share: 0.18, price: 90 },
  beverages: { share: 0.12, price: 85 }, staples: { share: 0.15, price: 110 }, personal_care: { share: 0.08, price: 150 }
};
const NEW_USER_PRICE_FACTOR = 0.92; // new users buy slightly cheaper baskets

// Business calendar the agent is told about (known events are not alerts).
const CALENDAR = [{ day: 84, name: 'ZipBasket Anniversary Sale (planned, all cities)' }];

// Planted incidents (the agent is NOT told about these).
const INCIDENTS = [
  { id: 'upi_failure', days: [61, 62], city: 'Bengaluru', note: 'UPI success rate collapses in Bengaluru; some users retry with card' },
  { id: 'dairy_stockout', days: [70, 71], city: 'Delhi', stores: ['Saket', 'Dwarka', 'Rohini'], note: 'Dairy out of stock most of the day in 3 Delhi stores' },
  { id: 'new_user_campaign', days: [78, 79, 80], note: 'Acquisition campaign triples new-user traffic; every segment behaves normally (mix shift)' },
  { id: 'anniversary_sale', days: [84], note: 'Planned sale, in the business calendar; should not alert' }
];

function dateOf(d) {
  const t = new Date(START + 'T00:00:00Z');
  t.setUTCDate(t.getUTCDate() + d);
  return t.toISOString().slice(0, 10);
}

function generate(seed) {
  const rnd = makeRng(seed || 42);
  const noise = sd => { let s = 0; for (let i = 0; i < 6; i++) s += rnd(); return Math.exp((s - 3) * Math.sqrt(2) * sd); };
  const funnel = [];   // date, city, store, user_type: sessions, checkouts
  const orders = [];   // date, city, store, user_type, payment: checkouts, orders, gmv, items
  const cats = [];     // date, city, store, category: items, gmv, stockout_hours
  const storeFactor = {};
  for (const [city, c] of Object.entries(CITIES)) c.stores.forEach(s => { storeFactor[s] = 0.8 + 0.4 * rnd(); });

  for (let d = 0; d < DAYS; d++) {
    const date = dateOf(d);
    const wd = new Date(date + 'T00:00:00Z').getUTCDay();
    const trend = 1 + 0.0015 * d;
    const sale = d === 84;
    const campaign = [78, 79, 80].includes(d);
    for (const [city, c] of Object.entries(CITIES)) {
      for (const store of c.stores) {
        const storeSessions = c.base * storeFactor[store] * WEEKDAY[wd] * trend * noise(0.022) * (sale ? 1.7 : 1);
        const stockout = INCIDENTS[1].days.includes(d) && city === 'Delhi' && INCIDENTS[1].stores.includes(store);
        const upiDown = INCIDENTS[0].days.includes(d) && city === 'Bengaluru';
        const catItems = {};
        for (const [ut, u] of Object.entries(USERS)) {
          const sessions = Math.round(storeSessions * u.share * (campaign && ut === 'new' ? 3.2 : 1) * noise(0.012));
          const checkoutRate = u.checkout * noise(0.012) * (sale ? 1.1 : 1) * (stockout ? 0.94 : 1);
          const checkouts = Math.round(sessions * checkoutRate);
          funnel.push({ date, city, store, user_type: ut, sessions, checkouts });
          let retryToCard = 0;
          for (const [pm, p] of Object.entries(PAYMENTS)) {
            let pmCheckouts = Math.round(checkouts * p.share * noise(0.008));
            let success = p.success * noise(0.006);
            if (pm === 'UPI' && upiDown) { success = 0.52 * noise(0.03); retryToCard = Math.round(pmCheckouts * (1 - success) * 0.35); }
            if (pm === 'Card') pmCheckouts += retryToCard;
            const ords = Math.min(pmCheckouts, Math.round(pmCheckouts * Math.min(success, 0.995)));
            const itemsPerOrder = u.items * noise(0.012) * (stockout ? 0.80 : 1);
            const items = Math.round(ords * itemsPerOrder);
            let gmv = 0;
            for (const [cat, cc] of Object.entries(CATEGORIES)) {
              let share = cc.share;
              if (stockout) share = cat === 'dairy' ? cc.share * 0.12 : cc.share * (1 + (0.22 * 0.88 * 0.3) / 0.78);
              const ci = items * share;
              const cg = ci * cc.price * (ut === 'new' ? NEW_USER_PRICE_FACTOR : 1) * noise(0.01);
              catItems[cat] = catItems[cat] || { items: 0, gmv: 0 };
              catItems[cat].items += ci; catItems[cat].gmv += cg; gmv += cg;
            }
            orders.push({ date, city, store, user_type: ut, payment: pm, checkouts: pmCheckouts, orders: ords, gmv: Math.round(gmv), items });
          }
        }
        for (const [cat, v] of Object.entries(catItems)) {
          const so = stockout && cat === 'dairy' ? 14 + Math.round(rnd() * 4) : (rnd() < 0.03 ? 1 + Math.round(rnd() * 2) : 0);
          cats.push({ date, city, store, category: cat, items: Math.round(v.items), gmv: Math.round(v.gmv), stockout_hours: so });
        }
      }
    }
  }
  return { start: START, days: DAYS, funnel, orders, cats, calendar: CALENDAR.map(e => ({ date: dateOf(e.day), name: e.name })) };
}


// ===== Detection and root cause (no AI) =====
// Metric Detective: anomaly detection + root cause (mix vs rate) on daily data. No AI, no dependencies.

const KPIS = ['gmv', 'orders', 'aov', 'sessions', 'conversion'];
const THRESH = { total: 0.05, city: 0.08, store: 0.15 }; // minimum % move to alert, per scope
const Z_MIN = 3;
const FLOOR = { total: 0.015, city: 0.025, store: 0.04 }; // minimum noise level assumed, per scope

function buildIndex(D) {
  const byDate = {};
  const add = (date, key, row) => { (byDate[date] = byDate[date] || { funnel: [], orders: [], cats: [] })[key].push(row); };
  D.funnel.forEach(r => add(r.date, 'funnel', r));
  D.orders.forEach(r => add(r.date, 'orders', r));
  D.cats.forEach(r => add(r.date, 'cats', r));
  return { byDate, dates: Object.keys(byDate).sort(), calendar: D.calendar || [] };
}

const inScope = (r, scope) => !scope || ((!scope.city || r.city === scope.city) && (!scope.store || r.store === scope.store));

function totals(idx, dates, scope) {
  const t = { sessions: 0, checkouts: 0, pay_checkouts: 0, orders: 0, gmv: 0, items: 0 };
  for (const d of dates) {
    const b = idx.byDate[d];
    b.funnel.forEach(r => { if (inScope(r, scope)) { t.sessions += r.sessions; t.checkouts += r.checkouts; } });
    b.orders.forEach(r => { if (inScope(r, scope)) { t.pay_checkouts += r.checkouts; t.orders += r.orders; t.gmv += r.gmv; t.items += r.items; } });
  }
  const n = dates.length;
  Object.keys(t).forEach(k => { t[k] /= n; });
  t.aov = t.gmv / t.orders; t.conversion = t.orders / t.sessions; t.checkout_rate = t.checkouts / t.sessions;
  t.payment_success = t.orders / t.pay_checkouts; t.items_per_order = t.items / t.orders; t.price_per_item = t.gmv / t.items;
  return t;
}

function baselineDates(idx, date) {
  const i = idx.dates.indexOf(date);
  const out = [];
  for (let k = 1; k <= 4; k++) if (i - 7 * k >= 0) out.push(idx.dates[i - 7 * k]);
  return out.length === 4 ? out : null;
}

function median(a) { const s = a.slice().sort((x, y) => x - y); const m = s.length >> 1; return s.length % 2 ? s[m] : (s[m - 1] + s[m]) / 2; }

function check(idx, date, scope, level) {
  const base = baselineDates(idx, date);
  if (!base) return [];
  const now = totals(idx, [date], scope);
  const hist = base.map(d => totals(idx, [d], scope));
  const out = [];
  for (const k of KPIS) {
    const vals = hist.map(h => h[k]);
    const med = median(vals);
    const mad = median(vals.map(v => Math.abs(v - med))) * 1.4826;
    const scale = Math.max(mad, FLOOR[level] * Math.abs(med));
    const pct = (now[k] - med) / med;
    const z = (now[k] - med) / scale;
    if (Math.abs(pct) >= THRESH[level] && Math.abs(z) >= Z_MIN) out.push({ level, scope: scope || {}, kpi: k, now: now[k], usual: med, pct, z });
  }
  return out;
}

function detect(idx, date) {
  const cityOf = {};
  idx.byDate[date].funnel.forEach(r => { cityOf[r.store] = r.city; });
  const cities = [...new Set(Object.values(cityOf))];
  let alerts = check(idx, date, null, 'total');
  cities.forEach(c => { alerts = alerts.concat(check(idx, date, { city: c }, 'city')); });
  Object.keys(cityOf).forEach(s => { alerts = alerts.concat(check(idx, date, { city: cityOf[s], store: s }, 'store')); });
  const event = idx.calendar.find(e => e.date === date);
  return { date, event: event ? event.name : null, alerts: event ? [] : alerts, suppressed: event ? alerts.length : 0 };
}

// Mix vs rate for a ratio metric R = sum(num) / sum(den) split by a dimension.
function mixRate(rows0, rows1, dim, num, den, n0) {
  const seg = {};
  const put = (rows, which, div) => rows.forEach(r => {
    const k = r[dim]; seg[k] = seg[k] || { n0: 0, d0: 0, n1: 0, d1: 0 };
    seg[k][which === 0 ? 'n0' : 'n1'] += r[num] / div; seg[k][which === 0 ? 'd0' : 'd1'] += r[den] / div;
  });
  put(rows0, 0, n0); put(rows1, 1, 1);
  const D0 = Object.values(seg).reduce((a, s) => a + s.d0, 0), D1 = Object.values(seg).reduce((a, s) => a + s.d1, 0);
  const N0 = Object.values(seg).reduce((a, s) => a + s.n0, 0), N1 = Object.values(seg).reduce((a, s) => a + s.n1, 0);
  const R0 = N0 / D0, R1 = N1 / D1;
  let mix = 0, rate = 0;
  const segs = Object.entries(seg).map(([k, s]) => {
    const w0 = s.d0 / D0, w1 = s.d1 / D1, r0 = s.d0 ? s.n0 / s.d0 : 0, r1 = s.d1 ? s.n1 / s.d1 : 0;
    const m = (w1 - w0) * (r0 - R0), rt = w1 * (r1 - r0);
    mix += (w1 - w0) * r0; rate += rt;
    return { segment: k, share_before: w0, share_now: w1, rate_before: r0, rate_now: r1, mix_effect: m, rate_effect: rt };
  });
  segs.sort((a, b) => Math.abs(b.rate_effect) + Math.abs(b.mix_effect) - Math.abs(a.rate_effect) - Math.abs(a.mix_effect));
  const totalAbsRate = segs.reduce((a, x) => a + Math.abs(x.rate_effect), 0) || 1;
  return { dim, before: R0, now: R1, change: R1 - R0, mix_effect: mix, rate_effect: rate, concentration: Math.abs(segs[0].rate_effect) / totalAbsRate, segments: segs.length, top: segs.slice(0, 3) };
}

function rowsFor(idx, dates, scope, key) {
  let out = [];
  dates.forEach(d => { out = out.concat(idx.byDate[d][key].filter(r => inScope(r, scope))); });
  return out;
}

// Join funnel + orders at store x user_type so conversion can be split by user type, city or store.
function userRows(idx, dates, scope) {
  const m = {};
  rowsFor(idx, dates, scope, 'funnel').forEach(r => { const k = r.date + r.store + r.user_type; m[k] = Object.assign({ orders: 0, gmv: 0, items: 0 }, r); });
  rowsFor(idx, dates, scope, 'orders').forEach(r => { const k = r.date + r.store + r.user_type; m[k].orders += r.orders; m[k].gmv += r.gmv; m[k].items += r.items; });
  return Object.values(m);
}

function explain(idx, date, alerts) {
  const alert = alerts[0];
  const scope = alert.scope && alert.scope.city ? alert.scope : null;
  const base = baselineDates(idx, date);
  const b = totals(idx, base, scope), n = totals(idx, [date], scope);
  const ln = (x, y) => Math.log(x / y);
  const gmvL = ln(n.gmv, b.gmv);
  const tree = {
    gmv: { before: b.gmv, now: n.gmv },
    orders: { before: b.orders, now: n.orders, share_of_gmv_change: ln(n.orders, b.orders) / gmvL },
    aov: { before: b.aov, now: n.aov, share_of_gmv_change: ln(n.aov, b.aov) / gmvL },
    sessions: { before: b.sessions, now: n.sessions },
    conversion: { before: b.conversion, now: n.conversion },
    checkout_rate: { before: b.checkout_rate, now: n.checkout_rate },
    payment_success: { before: b.payment_success, now: n.payment_success },
    items_per_order: { before: b.items_per_order, now: n.items_per_order },
    price_per_item: { before: b.price_per_item, now: n.price_per_item }
  };
  const u0 = userRows(idx, base, scope), u1 = userRows(idx, [date], scope);
  const p0 = rowsFor(idx, base, scope, 'orders'), p1 = rowsFor(idx, [date], scope, 'orders');
  const dims = [
    mixRate(u0, u1, 'user_type', 'orders', 'sessions', base.length),
    mixRate(p0, p1, 'payment', 'orders', 'checkouts', base.length),
    mixRate(u0, u1, 'user_type', 'gmv', 'orders', base.length)
  ];
  dims[0].metric = 'conversion'; dims[1].metric = 'payment_success'; dims[2].metric = 'aov';
  if (!scope || !scope.store) {
    const geo = scope ? 'store' : 'city';
    const a = mixRate(u0, u1, geo, 'orders', 'sessions', base.length); a.metric = 'conversion'; dims.push(a);
    const c = mixRate(u0, u1, geo, 'gmv', 'orders', base.length); c.metric = 'aov'; dims.push(c);
    const pg = mixRate(p0.filter(r => r.payment === 'UPI'), p1.filter(r => r.payment === 'UPI'), geo, 'orders', 'checkouts', base.length); pg.metric = 'upi_success'; dims.push(pg);
  }
  const c0 = rowsFor(idx, base, scope, 'cats'), c1 = rowsFor(idx, [date], scope, 'cats');
  const cat = {};
  c0.forEach(r => { cat[r.category] = cat[r.category] || { items_before: 0, items_now: 0, stockout_hours_now: 0 }; cat[r.category].items_before += r.items / base.length; });
  c1.forEach(r => { cat[r.category].items_now += r.items; cat[r.category].stockout_hours_now += r.stockout_hours; });
  const categories = Object.entries(cat).map(([k, v]) => ({ category: k, items_before: v.items_before, items_now: v.items_now, change: v.items_now / v.items_before - 1, stockout_hours_now: v.stockout_hours_now }))
    .sort((x, y) => Math.abs(y.change) - Math.abs(x.change)).slice(0, 3);
  // Verdict: is the alerting ratio metric moved by mix or by behaviour?
  // Verdict per ratio metric that alerted: moved by mix (who showed up) or by behaviour (what they did)?
  const verdicts = {};
  alerts.filter(a => ['aov', 'conversion'].includes(a.kpi)).forEach(a => {
    const userSplit = dims.find(d => d.metric === a.kpi && d.dim === 'user_type');
    verdicts[a.kpi] = userSplit && Math.abs(userSplit.mix_effect) > 2 * Math.abs(userSplit.rate_effect) ? 'mix_shift' : 'behaviour_change';
  });
  return { date, scope: alert.scope, alerts: alerts.map(a => ({ kpi: a.kpi, now: a.now, usual: a.usual, pct: a.pct })), baseline_days: base, tree, drivers: dims, categories, verdicts };
}

// One run: detect, keep the most important alerts, explain each distinct scope.
function run(D, date) {
  const idx = buildIndex(D);
  const det = detect(idx, date);
  const rank = { total: 0, city: 1, store: 2 };
  const scopeKey = a => (a.scope.city || 'all') + '/' + (a.scope.store || '');
  const seen = {};
  const picked = [];
  det.alerts.sort((a, b) => rank[a.level] - rank[b.level] || Math.abs(b.z) - Math.abs(a.z)).forEach(a => {
    const k = scopeKey(a);
    const coveredByCity = a.level === 'store' && seen[a.scope.city + '/'];
    const coveredByTotal = a.level !== 'total' && seen['all/'];
    if (seen[k] || coveredByCity || coveredByTotal) return;
    seen[k] = true; picked.push(a);
  });
  const allFor = a => det.alerts.filter(x => scopeKey(x) === scopeKey(a)).sort((p, q) => Math.abs(q.z) - Math.abs(p.z));
  const findings = picked.map(a => {
    const f = explain(idx, date, allFor(a));
    f.level = a.level;
    f.stores_also_alerting = [...new Set(det.alerts.filter(x => x.level === 'store' && (a.level === 'total' || x.scope.city === a.scope.city)).map(x => x.scope.store))];
    return f;
  });
  return { date, event: det.event, suppressed_alerts: det.suppressed, alert_count: det.alerts.length, alerts: det.alerts.map(a => ({ level: a.level, scope: a.scope, kpi: a.kpi, pct: a.pct })), findings };
}


// ===== Fact lines for the write-up =====
// Turns a run result into plain-English fact lines with fixed, pre-formatted numbers.
// The AI may only use these numbers; the checker compares against them.

const pct = x => (x * 100).toFixed(1) + '%';
const chg = x => (x >= 0 ? '+' : '') + (x * 100).toFixed(1) + '%';
const inr = x => 'Rs ' + Math.round(x).toLocaleString('en-IN');
const n0 = x => Math.round(x).toLocaleString('en-IN');
const NAMES = { gmv: 'GMV', orders: 'orders', aov: 'average order value', sessions: 'app sessions', conversion: 'conversion (orders per session)' };
const fmtKpi = (k, v) => k === 'gmv' || k === 'aov' ? inr(v) : (k === 'conversion' ? pct(v) : n0(v));
const DIM = { user_type: 'user type', payment: 'payment method', city: 'city', store: 'store' };
const METRIC = { conversion: 'conversion', payment_success: 'payment success rate', aov: 'average order value', upi_success: 'UPI payment success rate' };
const fmtRate = (m, v) => m === 'aov' ? inr(v) : pct(v);

function facts(result) {
  const lines = [];
  if (result.event) lines.push(`Known event today: ${result.event}. ${result.suppressed_alerts} alerts were suppressed because the business calendar expects unusual numbers.`);
  result.findings.forEach((f, i) => {
    const where = f.scope.store ? `${f.scope.store} store (${f.scope.city})` : (f.scope.city ? f.scope.city : 'all cities');
    lines.push(`FINDING ${i + 1}: ${where}, ${result.date}, compared with the average of the same weekday over the previous 4 weeks.`);
    const t = f.tree;
    f.alerts.forEach(a => { const u = t[a.kpi].before, v = t[a.kpi].now; lines.push(`- ${NAMES[a.kpi]}: usual ${fmtKpi(a.kpi, u)}, today ${fmtKpi(a.kpi, v)} (${chg(v / u - 1)}).`); });
    lines.push(`- Funnel, usual vs today: app sessions ${n0(t.sessions.before)} vs ${n0(t.sessions.now)}; checkout rate ${pct(t.checkout_rate.before)} vs ${pct(t.checkout_rate.now)}; payment success ${pct(t.payment_success.before)} vs ${pct(t.payment_success.now)}; items per order ${t.items_per_order.before.toFixed(2)} vs ${t.items_per_order.now.toFixed(2)}.`);
    f.drivers.forEach(d => {
      const big = Math.abs(d.rate_effect) + Math.abs(d.mix_effect);
      const rel = big / (d.metric === 'aov' ? d.before : Math.max(d.before, 1e-9));
      if (rel < 0.02) return;
      if (['city', 'store'].includes(d.dim) && d.concentration < 0.5) return; // spread evenly across places: not a local cause
      const s = d.top[0];
      const kind = Math.abs(d.mix_effect) > 2 * Math.abs(d.rate_effect) ? 'MIX (the share of each group changed, not their behaviour)' : 'BEHAVIOUR (a group behaved differently)';
      lines.push(`- ${METRIC[d.metric]} by ${DIM[d.dim]}: overall ${fmtRate(d.metric, d.before)} -> ${fmtRate(d.metric, d.now)}; driver type ${kind}. Biggest segment: ${s.segment}, ${fmtRate(d.metric, s.rate_before)} -> ${fmtRate(d.metric, s.rate_now)}, share ${pct(s.share_before)} -> ${pct(s.share_now)}.`);
    });
    const itemsChange = (t.orders.now * t.items_per_order.now) / (t.orders.before * t.items_per_order.before) - 1;
    f.categories.filter(c => Math.abs((1 + c.change) / (1 + itemsChange) - 1) >= 0.15 || c.stockout_hours_now >= 6).forEach(c =>
      lines.push(`- Category ${c.category}: items ${n0(c.items_before)} usual vs ${n0(c.items_now)} today (${chg(c.change)}); out-of-stock hours today across stores ${c.stockout_hours_now}.`));
    Object.entries(f.verdicts || {}).forEach(([k, v]) => lines.push(`- Verdict for ${NAMES[k]}: ${v === 'mix_shift' ? 'MIX SHIFT. Each user group behaved normally; the drop comes from more low-spend or low-converting users in the mix. Not a problem in itself.' : 'BEHAVIOUR CHANGE. Something changed for a specific group.'}`));
    const st = f.stores_also_alerting;
    if (st.length) lines.push(st.length > 5 ? `- ${st.length} of 20 stores also moved beyond their own thresholds.` : `- Stores also alerting: ${st.join(', ')}.`);
  });
  return lines;
}

// Numbers allowed in the email = numbers in the fact lines (plus the date parts).
function numbersIn(s) {
  return (String(s).replace(/(\d),(?=\d)/g, '$1').match(/\d+(?:\.\d+)?/g) || []);
}

function checkNumbers(text, factLines) {
  const allowed = new Set(numbersIn(factLines.join(' ')));
  const bad = numbersIn(text).filter(n => !allowed.has(n));
  return { ok: bad.length === 0, bad: [...new Set(bad)] };
}


// ===== Run for this item's date =====
const date = $json.date;
const result = run(generate(42), date);
const lines = facts(result);
return { json: {
  date: date,
  findings: result.findings.length,
  event: result.event,
  suppressed_alerts: result.suppressed_alerts,
  facts: lines,
  user_prompt: 'DATE: ' + date + '\nFACTS:\n' + lines.join('\n')
} };

// Numbers allowed in the email = numbers in the fact lines (plus the date parts).
function numbersIn(s) {
  return (String(s).replace(/(\d),(?=\d)/g, '$1').match(/\d+(?:\.\d+)?/g) || []);
}

function checkNumbers(text, factLines) {
  const allowed = new Set(numbersIn(factLines.join(' ')));
  const bad = numbersIn(text).filter(n => !allowed.has(n));
  return { ok: bad.length === 0, bad: [...new Set(bad)] };
}


function esc(s) { return String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;'); }
function parse(t) { const s = String(t || ''); const a = s.indexOf('{'), b = s.lastIndexOf('}'); try { return JSON.parse(s.slice(a, b + 1)); } catch (e) { return null; } }
function textOf(j) {
  if (typeof j.merged_response === 'string') return j.merged_response;
  if (Array.isArray(j.content)) return j.content.map(function (c) { return c.text || ''; }).join('');
  return j.text || j.output || '';
}
const src = $('Anything To Report?').all();
return $input.all().map(function (item, i) {
  const f = src[i].json;
  const draft = parse(textOf(item.json)) || {};
  const check = checkNumbers((draft.subject || '') + ' ' + (draft.body || ''), f.facts);
  const useAi = !!(draft.subject && draft.body && check.ok);
  const subject = useAi ? draft.subject : 'Metric alert ' + f.date + ': see computed findings';
  const body = useAi ? draft.body : f.facts.join('\n');
  const footer = useAi
    ? 'Every number above was matched against the computed table before sending.'
    : 'The AI draft was not used because it contained numbers not in the computed table (' + (check.bad.join(', ') || 'empty draft') + '). These are the computed findings.';
  const html = '<div style="font-family:Arial,sans-serif;font-size:14px;line-height:1.5;color:#1c1b19">' +
    '<div style="font-size:12px;color:#8a857b">ZipBasket Metric Detective · ' + esc(f.date) + ' (sample data)</div>' +
    esc(body).split('\n').map(function (l) { return l.trim() ? '<p style="margin:4px 0">' + l + '</p>' : ''; }).join('') +
    '<p style="margin-top:14px;font-size:12px;color:#1f6f4a">✔ ' + esc(footer) + '</p></div>';
  return { json: { date: f.date, subject: subject, body: body, html: html, ai_used: useAi, numbers_not_in_facts: check.bad } };
});
